Query#1: WITH o_counts AS (SELECT o_custkey, count(o_orderkey) AS c_count FROM orders WHERE o_comment NOT LIKE &&&_A GROUP BY o_custkey) SELECT COALESCE(o.c_count, 0) AS c_count, count(*) AS custdist FROM customer c LEFT JOIN o_counts o ON c.c_custkey = o.o_custkey GROUP BY COALESCE(o.c_count, 0) ORDER BY custdist DESC, c_count DESC;
Query#2: SELECT COALESCE(o.c_count, 0) AS c_count, count(*) AS custdist FROM customer c LEFT JOIN (SELECT o_custkey, count(o_orderkey) AS c_count FROM orders WHERE o_comment NOT LIKE &&&_A GROUP BY o_custkey) o ON c.c_custkey = o.o_custkey GROUP BY COALESCE(o.c_count, 0) ORDER BY custdist DESC, c_count DESC;
Query#3: WITH o_counts AS (SELECT o_custkey, count(o_orderkey) AS c_count FROM orders WHERE o_comment NOT LIKE &&&_A GROUP BY o_custkey) SELECT CASE WHEN o.c_count IS NULL THEN 0 ELSE o.c_count END AS c_count, count(*) AS custdist FROM customer c LEFT JOIN o_counts o ON c.c_custkey = o.o_custkey GROUP BY CASE WHEN o.c_count IS NULL THEN 0 ELSE o.c_count END ORDER BY custdist DESC, c_count DESC;
Query#4: SELECT COALESCE(o.c_count, 0) AS c_count, count(c.c_custkey) AS custdist FROM customer c LEFT JOIN (SELECT o_custkey, count(o_orderkey) AS c_count FROM orders WHERE o_comment NOT LIKE &&&_A GROUP BY o_custkey) o ON c.c_custkey = o.o_custkey GROUP BY COALESCE(o.c_count, 0) ORDER BY custdist DESC, c_count DESC;
Query#5: SELECT c_count, count(*) AS custdist FROM (SELECT c.c_custkey, COALESCE(o.c_count, 0) AS c_count FROM customer c LEFT JOIN (SELECT o_custkey, count(*) AS c_count FROM orders WHERE o_comment NOT LIKE &&&_A GROUP BY o_custkey) o ON c.c_custkey = o.o_custkey) AS c_orders GROUP BY c_count ORDER BY custdist DESC, c_count DESC;
Query#6: WITH filtered_orders AS (SELECT o_orderkey, o_custkey FROM orders WHERE o_comment NOT LIKE &&&_A) SELECT c_count, count(*) AS custdist FROM (SELECT c.c_custkey, count(fo.o_orderkey) AS c_count FROM customer c LEFT JOIN filtered_orders fo ON c.c_custkey = fo.o_custkey GROUP BY c.c_custkey) AS c_orders GROUP BY c_count ORDER BY custdist DESC, c_count DESC;
Query#7: SELECT c_count, count(*) AS custdist FROM (SELECT c.c_custkey, count(fo.o_orderkey) AS c_count FROM customer c LEFT JOIN (SELECT o_orderkey, o_custkey FROM orders WHERE o_comment NOT LIKE &&&_A) fo ON c.c_custkey = fo.o_custkey GROUP BY c.c_custkey) AS c_orders GROUP BY c_count ORDER BY custdist DESC, c_count DESC;
Query#8: SELECT c_count, count(*) AS custdist FROM (SELECT c.c_custkey, count(fo.o_custkey) AS c_count FROM customer c LEFT JOIN (SELECT o_custkey FROM orders WHERE o_comment NOT LIKE &&&_A) fo ON c.c_custkey = fo.o_custkey GROUP BY c.c_custkey) AS c_orders GROUP BY c_count ORDER BY custdist DESC, c_count DESC;
Query#9: WITH filtered_orders AS MATERIALIZED (SELECT o_orderkey, o_custkey FROM orders WHERE o_comment NOT LIKE &&&_A) SELECT c_count, count(*) AS custdist FROM (SELECT c.c_custkey, count(fo.o_orderkey) AS c_count FROM customer c LEFT JOIN filtered_orders fo ON c.c_custkey = fo.o_custkey GROUP BY c.c_custkey) AS c_orders GROUP BY c_count ORDER BY custdist DESC, c_count DESC;
Query#10: SELECT c_count, count(*) AS custdist FROM (SELECT c.c_custkey, fo.c_count FROM customer c LEFT JOIN LATERAL (SELECT count(o_orderkey) AS c_count FROM orders WHERE o_custkey = c.c_custkey AND o_comment NOT LIKE &&&_A) fo ON true) AS c_orders GROUP BY c_count ORDER BY custdist DESC, c_count DESC;
Query#11: SELECT c_count, count(*) AS custdist FROM (SELECT c.c_custkey, (SELECT count(o.o_orderkey) FROM orders o WHERE o.o_custkey = c.c_custkey AND o.o_comment NOT LIKE &&&_A) AS c_count FROM customer c) AS c_orders GROUP BY c_count ORDER BY custdist DESC, c_count DESC;
Query#12: SELECT c_count, count(c_custkey) AS custdist FROM (SELECT c.c_custkey, COALESCE((SELECT count(o.o_orderkey) FROM orders o WHERE o.o_custkey = c.c_custkey AND o.o_comment NOT LIKE &&&_A), 0) AS c_count FROM customer c) AS c_orders GROUP BY c_count ORDER BY custdist DESC, c_count DESC;
Query#13: WITH c_orders AS (SELECT c.c_custkey, count(o.o_orderkey) AS c_count FROM customer c LEFT OUTER JOIN orders o ON c.c_custkey = o.o_custkey AND o.o_comment NOT LIKE &&&_A GROUP BY c.c_custkey) SELECT c_count, count(*) AS custdist FROM c_orders GROUP BY c_count ORDER BY custdist DESC, c_count DESC;
Query#14: SELECT c_count, count(c_custkey) AS custdist FROM (SELECT c.c_custkey, count(o.o_orderkey) AS c_count FROM customer c LEFT OUTER JOIN orders o ON c.c_custkey = o.o_custkey AND o.o_comment NOT LIKE &&&_A GROUP BY c.c_custkey) AS c_orders GROUP BY c_count ORDER BY custdist DESC, c_count DESC;
Query#15: SELECT c_count, count(*) AS custdist FROM (SELECT c_custkey, count(o_custkey) AS c_count FROM customer LEFT OUTER JOIN orders ON c_custkey = o_custkey AND o_comment NOT LIKE &&&_A GROUP BY c_custkey) AS c_orders (c_custkey, c_count) GROUP BY c_count ORDER BY custdist DESC, c_count DESC;
Query#16: SELECT c_orders.c_count, count(*) AS custdist FROM (SELECT c.c_custkey, count(o.o_orderkey) AS c_count FROM customer c LEFT OUTER JOIN orders o ON c.c_custkey = o.o_custkey AND o.o_comment NOT LIKE &&&_A GROUP BY c.c_custkey) AS c_orders GROUP BY c_orders.c_count ORDER BY custdist DESC, c_orders.c_count DESC;
Query#17: SELECT c_count, count(1) AS custdist FROM (SELECT c_custkey, count(o_orderkey) AS c_count FROM customer LEFT OUTER JOIN orders ON c_custkey = o_custkey AND o_comment NOT LIKE &&&_A GROUP BY c_custkey) AS c_orders GROUP BY c_count ORDER BY custdist DESC, c_count DESC;
Query#18: SELECT c_orders.c_count, count(c_orders.c_custkey) AS custdist FROM (SELECT customer.c_custkey, count(orders.o_orderkey) AS c_count FROM customer LEFT OUTER JOIN orders ON customer.c_custkey = orders.o_custkey AND orders.o_comment NOT LIKE &&&_A GROUP BY customer.c_custkey) AS c_orders GROUP BY c_orders.c_count ORDER BY custdist DESC, c_orders.c_count DESC;
Query#19: SELECT c_count, count(*) AS custdist FROM (SELECT c_custkey, count(o_orderkey) AS c_count FROM customer LEFT OUTER JOIN orders ON c_custkey = o_custkey AND o_comment NOT LIKE &&&_A GROUP BY c_custkey) AS c_orders GROUP BY c_count ORDER BY custdist DESC, c_count DESC;
Query#20: SELECT c_count, count(*) AS custdist FROM (SELECT c_custkey, count(o_orderkey) FROM customer LEFT OUTER JOIN orders ON c_custkey = o_custkey AND o_comment NOT LIKE &&&_A GROUP BY c_custkey) AS c_orders (c_custkey, c_count) GROUP BY c_count ORDER BY custdist DESC, c_count DESC;